SELECT COUNT(*) > 0 FROM registrations 
WHERE activity_id = #{activityId} AND student_phone = #{studentPhone} 
AND registration_status = 1 AND is_deleted = 0

SELECT  FROM registrations 
WHERE activity_id = #{activityId} AND student_phone = #{studentPhone} 
AND registration_status = 1 AND is_deleted = 0 LIMIT 1

SELECT  FROM registrations r LEFT JOIN activities
       a ON r.activity_id = a.id AND a.is_deleted = 0 WHERE r.is_deleted = 0  AND r.activity_id = #{activityId} 
        AND r.student_name LIKE CONCAT('%',
       #{studentName}, '%') 
        AND
       r.student_phone = #{studentPhone} 
        AND r.student_college LIKE
       CONCAT('%', #{studentCollege}, '%') 
        AND
       r.registration_status = #{registrationStatus} 
        AND
       r.check_in_status = #{checkInStatus}  
       ORDER BY r.create_time DESC

